/**
 * Generated records-per-page selector — port of the inline setPerPage()
 * script from site_builder/views/donor_manage.php.
 */
export const PER_PAGE_SELECT_TEMPLATE = `"use client";

import { BASE_URL } from "@/engine/config";

/**
 * Records-per-page selector.
 * Generated by Flo.
 */
export function PerPageSelect({
  options,
  selected,
  module,
}: {
  options: number[];
  selected: number;
  module: string;
}) {
  const base = BASE_URL.endsWith("/") ? BASE_URL : BASE_URL + "/";

  return (
    <select
      name="per_page"
      defaultValue={String(selected)}
      onChange={(event) => {
        window.location.href =
          base + module + "/set_per_page/" + event.target.value;
      }}
      className="h-8 rounded-md border border-input bg-background px-2 text-sm shadow-xs outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50"
    >
      {options.map((option, index) => (
        <option key={index} value={index}>
          {option}
        </option>
      ))}
    </select>
  );
}
`;
